//wajp to find sum of all elements.
package module10.arrays;

public class sum {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int[] arr = {12,14,16,22,18};
		int sum = 0;
		for(int i = 0; i<arr.length; i++) {
			sum = sum+arr[i];
			
		}
		System.out.println(sum);

	}

}
